#define SIZE 240.

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    vec2 cellUV = fract(uv * SIZE);
    vec2 stepUV = floor(uv * SIZE)/SIZE;

    vec3 col = texture(iChannel0, stepUV).rgb;

    vec3 lcdcol = vec3(0.);

    lcdcol += step(cellUV.x, 0.33) * col.x * vec3(1.,0.,0.);
    lcdcol += step(cellUV.x, 0.66) * step(0.33, cellUV.x) * col.y * vec3(0.,1.,0.);
    lcdcol += step(0.66, cellUV.x) * col.z * vec3(0.,0.,1.);

    // Output to screen
    fragColor = vec4(lcdcol.xyz,1.0);
}
